/**
 * Splits metadata.files.items into individual download messages.
 * Mirrors Fetch Wasos files — Prepare download list.
 */
const entry = msg.payload;
const items = msg.metadata.files.items;
const total = items.length;

const dl = {
    entry_backup: JSON.parse(JSON.stringify(entry, (k, v) => k === '_buffer' ? undefined : v)),
    connection_name: msg.metadata.connection_name,
    message_id: entry.id,
    metadata: msg.metadata
};

const to_download = [];

items.forEach((file, i) => {
    const parts = { id: msg._msgid, type: "array", count: total, index: i };
    to_download.push({
        _msgid:   msg._msgid,
        payload:  file,
        metadata: msg.metadata,
        _dl:      dl,
        parts:    parts
    });
});

return to_download.length ? [to_download] : null;

const utils = global.get("utils");
const target_attr = utils.get_system_attributes(msg.metadata.target.client_system);

// Skip failed downloads or empty responses
if (!msg.payload || msg.payload.length === 0 || msg.statusCode !== 200) {
    return [null, msg];
}

// Route oversized files to compression
if (target_attr.max_upload_bytes && msg.payload.length > target_attr.max_upload_bytes) {
    return [msg, null];
}
return [null, msg];

/**
 * Stores the downloaded file buffer in global context.
 * Returns a pruned file result object for the join node.
 * Mirrors Fetch Wasos files — Store file via global context.
 *
 * For Rayvn signed URLs the guessed type/name in _file_meta may be wrong
 * (Azure blob URLs have no filename in path). Actual Content-Type and
 * Content-Disposition headers from the HTTP response are used when available.
 */
const utils = global.get("utils");
const meta  = msg._file_meta;
const dl    = msg._dl;
const success = msg.statusCode === 200 && msg.payload && msg.payload.length > 0;

// Resolve actual content-type from response headers
const headers     = msg.responseHeaders || {};
const raw_ct      = headers['content-type'] || headers['Content-Type'] || meta.type || "application/octet-stream";
const actual_type = raw_ct.split(";")[0].trim();

// Resolve filename from Content-Disposition, falling back to _file_meta
let actual_name = meta.name;
const disposition = headers['content-disposition'] || headers['Content-Disposition'] || "";
const cd_match = disposition.match(/filename\*?=['"]?(?:UTF-8'')?([^;'"\r\n]+)/i);
if (cd_match) {
    actual_name = decodeURIComponent(cd_match[1].trim());
} else if (!actual_name || actual_name === "attachment" || !actual_name.includes(".")) {
    // Derive extension from content-type as fallback
    const ext_map = {
        "image/jpeg":       ".jpg",
        "image/png":        ".png",
        "image/gif":        ".gif",
        "image/webp":       ".webp",
        "application/pdf":  ".pdf",
        "video/mp4":        ".mp4"
    };
    const ext = ext_map[actual_type] || "";
    actual_name = (actual_name || "attachment") + ext;
}

const file = { name: actual_name, type: actual_type, size: meta.size, downloaded: success };

if (success) {
    const key = utils.build_file_key(dl.message_id, dl.connection_name, actual_name);
    global.set("files." + key, msg.payload);
    file.context_key = key;
    node.log("Stored: " + actual_name + " (" + actual_type + ", " + msg.payload.length + " bytes)");
} else {
    node.warn("File download failed. Status: " + msg.statusCode + ", file: " + actual_name);
}

return {
    _msgid:  msg._msgid,
    topic:   msg.topic,
    payload: file,
    parts:   msg.parts,
    _dl:     msg._dl
};

/**
 * Separates successful downloads from failures, rebuilds entry.
 * Mirrors Fetch Wasos files — Merge files and rebuild entry.
 */
const utils      = global.get("utils");
const dl         = msg._dl;
const entry      = dl.entry_backup;
const metadata   = dl.metadata;
const downloaded = Array.isArray(msg.payload) ? msg.payload : [msg.payload];

const stored = downloaded.filter(f => f.downloaded);
const failed = downloaded
    .filter(f => !f.downloaded)
    .map(f => ({ name: f.name || "ukjent fil", reason: f.reason || utils.FILE_REASONS.DOWNLOAD_FAILED }));

entry.files       = stored;
entry.failed_files = [...(entry.failed_files || []), ...failed];

metadata.files.items  = stored;
metadata.files.failed = [...metadata.files.failed, ...failed];

node.log("File download complete for entry " + entry.id + ": "
    + stored.length + " stored, " + failed.length + " failed");

return {
    _msgid:   msg._msgid,
    topic:    msg.topic,
    payload:  entry,
    metadata: metadata
};
